      WidgetTester tester,
      MemoryExecutionEnv env,
      String appId,
      String readyText,
    ) async {
      final permissions = await tester.runAsync(
        () => AppPermissionsStore.load(env),
      );
      await tester.pumpWidget(
        MaterialApp(
          theme: buildFahTheme(),
          locale: const Locale('en'),
          localizationsDelegates: AppLocalizations.localizationsDelegates,
