    this.asrTranscriber,
    this.notify,
    this.mediaGateway,
    this.videoReader,
    this.keysSource,
    this.keyRequestHandler,
    this.themeBridge,
    this.webViewHost,
    this.onEmit,
    this.hostLocale = 'en',
    this.initialTheme = const {},
    this.errorSink,
    this.joinSiblingGroup = true,
    this._onLog,
  });

