          mapTileProvider: widget.mapTileProvider,
          mediaHost: widget.mediaHost ?? const FaMediaHost(),
          // Embedded web content: the SAME host the engine's JsRuntimeConfig
          // got (see JsAppEngine.start), so a `webView` node renders
