    required this.reply,
    this.onExpand,
    this.onDismiss,
  });

  /// The session's service — only used for the orbit treatment: the Fa mark
  /// spins while the agent streams and is static otherwise.
  final AgentService service;

  /// The assistant reply text (Markdown).
  final String reply;

