  final old = _engine;
  _engine = null;
  if (old != null) await old.dispose();
  backHandlerRegistered.value = false;

  if (!app.supportsPlatform(currentFaPlatform)) {
    throw StateError("App '${app.id}' is not enabled on $currentFaPlatform");
