                MediaQuery.sizeOf(context).width <=
                    kDynamicTileFullWidthBreakpoint
                ? 0
                : 12,
            vertical: 6,
          ),
          decoration: BoxDecoration(
            border: Border.all(color: Theme.of(context).dividerColor),
            borderRadius: BorderRadius.circular(12),
