    await pumpAppRoute(tester, env, 'noback', 'NOBACK-READY');

    await systemBack(tester);

    expect(find.byType(JsAppView), findsNothing);
    expect(find.text('open-app'), findsOneWidget);
    await unmount(tester);
  });

