  /// `jsr.theme` and invokes `jsr._onThemeChange(theme)` when the app
  /// subscribed. No-op before [start] completes.
  Future<void> updateTheme(Map<String, dynamic> theme) {
    _engine?.updateTheme(theme);
    return Future.value();
