    DynamicMessagesService service() => DynamicMessagesService(
      env: MemoryExecutionEnv(),
      sendText: (_) async {},
      sessionIdOf: () => 's1',
      sessionFileOf: () => 'sessions/s1.json',
      mediaGatewayOf: () => null,
      videoReaderOf: () => null,
