''';

void main() {
  group('DynamicWidgetTile voxel node (gh-1441 IT-2)', () {
    TestWidgetsFlutterBinding.ensureInitialized();

    DynamicMessageDefinition definition(String id) =>
        DynamicMessageDefinition(
          id: id,
          title: 'Voxel sandbox',
          jsSource: voxelTileSource,
