              'type': 'voxel',
              'id': 'world',
            }, context),
          ),
        ),
      );
      expect(find.byIcon(Icons.landscape), findsOneWidget);
      expect(find.text('Voxel world'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });
  });
}
