      // The canvas wired the engine's bridge world: the real node paints.
      expect(find.byType(JsVoxelNode), findsOneWidget);
      expect(find.byIcon(Icons.landscape), findsNothing);
      expect(find.text('Voxel world'), findsNothing);
    });
  });
